(()=>{'use strict';
 const api=async(path,body)=>{const r=await fetch('/api/admin/print/'+path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined,cache:'no-store'}),d=await r.json();if(!r.ok)throw Error(d.error||'Печать недоступна');return d;};
 const el=(tag,value)=>{const n=document.createElement(tag);if(value!==undefined)n.textContent=value;return n;},money=n=>(n/100).toLocaleString('ru-RU',{minimumFractionDigits:2})+' ₽';
 const statuses={queued:'В очереди',received:'Получено агентом',printing:'Передаётся на печать',printed:'CUPS завершил задание',failed:'Ошибка — проверьте принтер',cancelled:'Снято до передачи принтеру'};
 const action=(title,fn)=>{const b=el('button',title);b.type='button';b.onclick=async()=>{b.disabled=true;try{await fn();}catch(e){const box=b.closest('.print-panel');if(box)box.querySelector('[role=status]').textContent=e.message;}finally{b.disabled=false;}};return b;};
 const healthState=d=>!d.enabled?'Печать не включена':!d.configured?'Ожидает настройки подключения':!d.online?'Ожидает связи с принтером':!d.health?.printing_enabled?'Агент на связи · физическая печать отключена':!d.health?.printer_configured?'Агент на связи · принтер не настроен':'Агент на связи';
 const health=d=>healthState(d)+(d.health?.local_ip?' · '+(d.online?'IP Raspberry Pi: ':'Последний IP Raspberry Pi: ')+d.health.local_ip+(d.lastSeen?' · Связь: '+new Date(d.lastSeen).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}):''):' · IP Raspberry Pi пока не получен');
 function askReason(message,anchor){return new Promise(resolve=>{const box=anchor.closest('.print-panel'),form=el('form');form.dataset.printReason='true';form.append(el('p',message));const label=el('label','Причина'),input=el('input');input.required=true;input.maxLength=300;input.setAttribute('aria-label','Причина печати');label.append(input);const save=el('button','Подтвердить печать');save.type='submit';const close=()=>finish(null),dialog=box.closest('dialog'),finish=value=>{dialog?.removeEventListener('close',close);form.remove();resolve(value);};form.append(label,save,action('Отмена',()=>finish(null)));form.onsubmit=e=>{e.preventDefault();if(input.value.trim())finish(input.value.trim());};box.append(form);dialog?.addEventListener('close',close,{once:true});input.focus();form.scrollIntoView({block:'nearest'});});}
 let currentDialog=null,refreshDialog=null,cafePanel=null,cafeRefresh=null;
 function panel(){const box=el('div');box.className='print-panel';const status=el('p');status.setAttribute('role','status');box.append(status);return box;}
 function jobRow(j,canEdit,reload){const row=el('div');row.className='print-job';row.append(el('span',`${j.operation==='reprint'?'ПОВТОР · ':''}${statuses[j.status]||j.status}${j.cups_id?' · CUPS №'+j.cups_id:''}`));
  if(canEdit&&['printed','failed'].includes(j.status))row.append(action('Повторная печать',async()=>{const reason=await askReason('Проверьте принтер: повтор создаст ещё один чек с пометкой «ПОВТОР».',row);if(!reason?.trim())return;await api('reprint',{jobId:j.id,reason});await reload();}));return row;}
 async function reportDialog(shiftId){currentDialog?.close();const dialog=el('dialog'),box=panel();dialog.className='print-dialog';box.append(el('h2','Отчёт смены'));const content=el('div');box.append(content,action('Закрыть',()=>dialog.close()));dialog.append(box);document.body.append(dialog);currentDialog=dialog;
  const reload=async()=>{const info=await api('report'+(shiftId?'?shiftId='+shiftId:'')),latest=info.reports[0],snapshot=latest?.snapshot||info.snapshot;content.replaceChildren();box.querySelector('[role=status]').textContent=health(info.device);content.append(el('h3',(snapshot.preliminary?'Предварительный':'Итоговый')+' · '+snapshot.date),el('strong','Кафе + прокат: '+money(snapshot.totalCents)),el('p','К переводу за эту смену:'));
   const unpaid=snapshot.employees.filter(e=>e.remainingCents>0);for(const e of unpaid)content.append(el('p',e.name+' — '+money(e.remainingCents)));if(!unpaid.length)content.append(el('p','Переводов нет'));
   content.append(el('small','Снимок: '+new Date(snapshot.asOf).toLocaleString('ru-RU',{timeZone:'Europe/Moscow'})));
   if(snapshot.preliminary)content.append(el('p','Предварительный расчёт. Итог определяется после сверки кассы.'));
   if(latest){content.append(jobRow(latest,true,reload),action('Обновить отчёт и напечатать',async()=>{const reason=await askReason('Будет создана новая редакция с актуальными суммами.',content);if(!reason?.trim())return;await api('report',{shiftId:snapshot.shiftId,newRevision:true,previousDocumentId:latest.document_id,reason});await reload();}));}
   else content.append(action('Напечатать отчёт',async()=>{await api('report',{shiftId:snapshot.shiftId});await reload();}));
   const note=el('small','Статус CUPS подтверждает передачу задания, а не выход бумаги.');content.append(note);
   if(info.reports.length>1){const history=el('details');history.append(el('summary','Предыдущие редакции'));for(const j of info.reports.slice(1))history.append(el('p',`${new Date(j.snapshot.asOf).toLocaleString('ru-RU')} · ${money(j.snapshot.totalCents)} · ${statuses[j.status]}`));content.append(history);}
  };
  dialog.addEventListener('close',()=>{if(currentDialog===dialog){currentDialog=null;refreshDialog=null;}dialog.remove();});dialog.showModal();refreshDialog=reload;
  try{await reload();}catch(e){box.querySelector('[role=status]').textContent=e.message;}
 }
 function reportPreview(info){
  const latest=info.reports[0],s=latest?.snapshot||info.snapshot,p=latest?.payload||{date:s.date,shift_id:String(s.shiftId),preliminary:s.preliminary,revision:1,total:(s.totalCents/100).toFixed(2),transfers:s.employees.filter(e=>e.remainingCents>0).map(e=>({recipient:e.name,amount:(e.remainingCents/100).toFixed(2)})),as_of:new Date(s.asOf).toISOString(),report_id:`start-shift-${s.shiftId}-${s.preliminary?'preliminary':'final'}-v1`};
  const rows=['КАФЕ СТАРТ',''];if(latest?.operation==='reprint')rows.push('*** ПОВТОР ***','');if(p.revision>1)rows.push('НОВАЯ РЕДАКЦИЯ '+p.revision);
  rows.push(p.preliminary?'ПРЕДВАРИТЕЛЬНЫЙ ОТЧЁТ':'ИТОГОВЫЙ ОТЧЁТ','Дата: '+p.date,'Смена: '+p.shift_id,'','КАФЕ + ПРОКАТ','СУММА ЗА СМЕНУ: '+p.total+' ₽','','КОМУ СКОЛЬКО ПЕРЕВЕСТИ:');
  for(const row of p.transfers)rows.push(row.recipient,row.amount+' ₽');if(!p.transfers.length)rows.push('Переводов нет');
  rows.push('Всего к выплате: '+(p.transfers.reduce((sum,row)=>sum+Math.round(Number(row.amount)*100),0)/100).toFixed(2)+' ₽','Только за эту смену; выплаты учтены.');
  if(p.preliminary)rows.push('Предварительно, до сверки кассы.');
  if(p.as_of)rows.push('Снимок: '+new Date(p.as_of).toLocaleString('ru-RU',{timeZone:'Europe/Moscow',day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).replace(',','')+' МСК');
  rows.push('','Отчёт: '+p.report_id);return rows.join('\n');
 }
 function mountReport(container,{shiftId,preview=false}={}){if(!container)return;container.replaceChildren();const box=panel(),print=action('Напечатать отчёт',async()=>{const result=await api('report',shiftId?{shiftId}:{});await reportDialog(result.job.snapshot.shiftId);});container.append(box);
  if(!preview){box.append(print);return;}
  const title=el('h3','На бумаге будет'),paper=el('pre'),note=el('small','Время получения добавится при выходе отчёта.');paper.className='print-report-preview';paper.setAttribute('aria-label','Предпросмотр отчёта смены');
  const status=box.querySelector('[role=status]');const reload=async()=>{print.disabled=true;retry.hidden=true;status.textContent='Загружаем отчёт…';try{const info=await api('report'+(shiftId?'?shiftId='+shiftId:''));paper.textContent=reportPreview(info);status.textContent=info.reports.length?'Показана сохранённая редакция отчёта.':'';print.disabled=false;}catch(e){status.textContent=e.message;retry.hidden=false;}};
  const retry=action('Повторить загрузку',reload);retry.hidden=true;box.append(title,paper,note,retry,print);reload();
 }
 function mountCafe(container,orderId,canEdit){if(!container)return;const box=panel();container.append(box);cafePanel=box;const reload=async()=>{const d=await api('cafe?orderId='+orderId);if(!box.isConnected)return;box.replaceChildren();const status=el('p',health(d.device));status.setAttribute('role','status');box.append(status);if(!d.jobs.length)box.append(el('small','Заданий печати для этого заказа нет. Автопечать действует для новых заказов после включения.'));for(const j of d.jobs){const title={NEW:'Заказ',ADD:'Дозаказ',CANCELLED:'Отмена',LOCATION:'Место'}[j.snapshot.eventKind]||'Чек';box.append(el('small',title),jobRow(j,canEdit,reload));}};cafeRefresh=reload;reload().catch(e=>box.querySelector('[role=status]').textContent=e.message);}
 setInterval(()=>{if(document.hidden)return;if(currentDialog?.open&&!currentDialog.querySelector('[data-print-reason]'))refreshDialog?.().catch(()=>{});if(cafePanel?.isConnected&&cafePanel.closest('dialog')?.open&&!cafePanel.querySelector('[data-print-reason]'))cafeRefresh?.().catch(()=>{});},15000);
 window.STARTPrint={mountReport,mountCafe};
})();
